1	interface Item {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	}
6	
7	interface QuoteStep {
8	  op: "quote";
9	  items: Item[];
10	}
11	
12	interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	interface ClaimStep {
18	  op: "claim";
19	  policy: number;
20	  incident: { cause: string; damages: Damage[] };
21	}
22	
23	type Step = QuoteStep | ClaimStep;
24	
25	interface Scenario {
26	  customer: { yearsWithMHPCO: number };
27	  steps: Step[];
28	}
29	
30	interface QuoteResult {
31	  premium: number;
32	}
33	
34	interface ClaimResult {
35	  payout: number;
36	  remainingCap: number;
37	}
38	
39	type StepResult = QuoteResult | ClaimResult;
40	
41	const BASE_PREMIUM: Record<string, number> = {
42	  sword: 100,
43	  amulet: 60,
44	  staff: 80,
45	  potion: 40,
46	  rune: 25,
47	};
48	
49	// The item types the office insures, mapped to their insured value. Doubles as
50	// the registry of "known" types for quote validation (isKnownType) and as the
51	// basis for a policy's cap (insuranceSum).
52	const INSURANCE_VALUE: Record<string, number> = {
53	  sword: 1000,
54	  amulet: 600,
55	  staff: 800,
56	  potion: 400,
57	  rune: 250,
58	  moonstone: 250,
59	};
60	
61	const PROCESSING_FEE = 5;
62	const FIRST_INSURANCE_SURCHARGE = 0.1;
63	
64	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
65	const COMPONENT_UNIT_PREMIUM = 25;
66	const COMPONENT_BLOCK_SIZE = 3;
67	const COMPONENT_BLOCK_PREMIUM = 60;
68	
69	const componentGroupBase = (count: number): number =>
70	  count === COMPONENT_BLOCK_SIZE
71	    ? COMPONENT_BLOCK_PREMIUM
72	    : count * COMPONENT_UNIT_PREMIUM;
73	
74	const componentsBase = (components: Item[]): number => {
75	  const countsByType = new Map<string, number>();
76	  for (const component of components) {
77	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
78	  }
79	  return [...countsByType.values()].reduce(
80	    (total, count) => total + componentGroupBase(count),
81	    0,
82	  );
83	};
84	
85	const isComponent = (item: Item): boolean =>
86	  COMPONENT_TYPES.has(item.type);
87	
88	const itemsBase = (items: Item[]): number => {
89	  const mainBase = items
90	    .filter((item) => !isComponent(item))
91	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
92	  return mainBase + componentsBase(items.filter(isComponent));
93	};
94	
95	const CURSE_SURCHARGE = 0.5;
96	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
97	const HIGH_ENCHANTMENT_THRESHOLD = 5;
98	
99	// Sum `rate * base premium` for every item matching `applies`. The additive
100	// per-item form keeps each surcharge a flat term so quotePremium stays additive
101	// (see the float-drift note there).
102	const itemSurcharge = (
103	  items: Item[],
104	  applies: (item: Item) => boolean,
105	  rate: number,
106	): number =>
107	  items.reduce(
108	    (sum, item) => sum + (applies(item) ? BASE_PREMIUM[item.type] * rate : 0),
109	    0,
110	  );
111	
112	const curseSurcharge = (items: Item[]): number =>
113	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE);
114	
115	const highEnchantmentSurcharge = (items: Item[]): number =>
116	  itemSurcharge(
117	    items,
118	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
119	    HIGH_ENCHANTMENT_SURCHARGE,
120	  );
121	
122	const LOYALTY_DISCOUNT = 0.2;
123	const LOYALTY_THRESHOLD_YEARS = 2;
124	const FOLLOWUP_DISCOUNT = 0.15;
125	
126	const loyaltyDiscount = (base: number, yearsWithMHPCO: number): number =>
127	  yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? base * LOYALTY_DISCOUNT : 0;
128	
129	const followupDiscount = (base: number, isFollowup: boolean): number =>
130	  isFollowup ? base * FOLLOWUP_DISCOUNT : 0;
131	
132	// Always-on surcharge charged on every policy, expressed as a flat term so
133	// quotePremium stays additive (see the float-drift note there).
134	const firstInsuranceSurcharge = (base: number): number =>
135	  base * FIRST_INSURANCE_SURCHARGE;
136	
137	const isKnownType = (type: string): boolean => type in INSURANCE_VALUE;
138	
139	const assertKnownItems = (items: Item[]): void => {
140	  for (const item of items) {
141	    if (!isKnownType(item.type)) {
142	      throw new Error(`Unknown item type: ${item.type}`);
143	    }
144	  }
145	};
146	
147	const quotePremium = (
148	  items: Item[],
149	  yearsWithMHPCO: number,
150	  isFollowup: boolean,
151	): number => {
152	  assertKnownItems(items);
153	  const base = itemsBase(items);
154	  const surcharges =
155	    firstInsuranceSurcharge(base) +
156	    curseSurcharge(items) +
157	    highEnchantmentSurcharge(items);
158	  const discounts =
159	    loyaltyDiscount(base, yearsWithMHPCO) + followupDiscount(base, isFollowup);
160	  // Sum flat terms rather than scaling `base * (1 + rate)`: the additive form
161	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
162	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
163	};
164	
165	const DEDUCTIBLE = 100;
166	const CAP_MULTIPLIER = 2;
167	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
168	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
169	
170	const insuranceSum = (items: Item[]): number =>
171	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
172	
173	// Reimbursement for a single damage before the deductible. Items enchanted to
174	// level 8+ are reimbursed at only 50% of the damage amount.
175	const reimbursement = (item: Item, amount: number): number =>
176	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
177	    ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT
178	    : amount;
179	
180	// The policy item a damage refers to, matched by type. Throws if the damage
181	// references an item the policy does not cover.
182	const policyItemFor = (damage: Damage, policyItems: Item[]): Item => {
183	  const item = policyItems.find((i) => i.type === damage.itemType);
184	  if (item === undefined) {
185	    throw new Error(`Item not in policy: ${damage.itemType}`);
186	  }
187	  return item;
188	};
189	
190	// Each damaged item is reimbursed (subject to clauses) less one deductible,
191	// floored in MHPCO's favor.
192	const damagesPayout = (damages: Damage[], policyItems: Item[]): number =>
193	  Math.floor(
194	    damages.reduce((sum, damage) => {
195	      const item = policyItemFor(damage, policyItems);
196	      return sum + (reimbursement(item, damage.amount) - DEDUCTIBLE);
197	    }, 0),
198	  );
199	
200	const claimResult = (
201	  claim: ClaimStep,
202	  policyItems: Item[],
203	  remainingCap: number,
204	): ClaimResult => {
205	  const desired = damagesPayout(claim.incident.damages, policyItems);
206	  const payout = Math.min(desired, remainingCap);
207	  return { payout, remainingCap: remainingCap - payout };
208	};
209	
210	// A policy's cap starts at twice its insurance sum and is drawn down by each
211	// claim. remainingCapByPolicy tracks the running balance keyed by policy step
212	// index, seeding the initial cap the first time a policy is claimed against.
213	const settleClaim = (
214	  claim: ClaimStep,
215	  steps: Step[],
216	  remainingCapByPolicy: Map<number, number>,
217	): ClaimResult => {
218	  const policyItems = (steps[claim.policy] as QuoteStep).items;
219	  const remainingCap =
220	    remainingCapByPolicy.get(claim.policy) ??
221	    CAP_MULTIPLIER * insuranceSum(policyItems);
222	  const result = claimResult(claim, policyItems, remainingCap);
223	  remainingCapByPolicy.set(claim.policy, result.remainingCap);
224	  return result;
225	};
226	
227	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
228	  const remainingCapByPolicy = new Map<number, number>();
229	  const results = scenario.steps.map((step, index): StepResult => {
230	    if (step.op === "claim") {
231	      return settleClaim(step, scenario.steps, remainingCapByPolicy);
232	    }
233	    // Every quote after the first is a follow-up contract; the map index is
234	    // already the count of quotes seen so far, so no separate counter is needed.
235	    const isFollowup = index > 0;
236	    return {
237	      premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, isFollowup),
238	    };
239	  });
240	  return { results };
241	};
